package com.elogistic.backend.merchant.internal.infrastructure;
import com.elogistic.backend.merchant.api.customer.OrganizationContacts;
import com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers;
import com.elogistic.backend.merchant.api.customer.OrganizationContactTransfers.*;
import com.elogistic.backend.merchant.internal.application.port.MerchantFingerprints;
import com.elogistic.backend.merchant.internal.domain.OrganizationContactCsv;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import tools.jackson.databind.json.JsonMapper;

public final class JdbcOrganizationContactTransfers implements OrganizationContactTransfers {
    private static final JsonMapper JSON=JsonMapper.builder().build();private final JdbcTemplate jdbc;private final JdbcOrganizationContacts contacts;private final MerchantFingerprints hashes;private final Clock clock;
    public JdbcOrganizationContactTransfers(DataSource source,JdbcOrganizationContacts contacts,MerchantFingerprints hashes,Clock clock){jdbc=new JdbcTemplate(source);this.contacts=contacts;this.hashes=hashes;this.clock=clock;}
    private static OrganizationContacts.Failure fail(String code){return new OrganizationContacts.Failure(code);}
    private void permit(OrganizationContacts.Access a,UUID facility){contacts.permit(a,"contacts.write",facility);contacts.permit(a,"contacts.import",facility);}
    private record Meta(UUID org,UUID facility,UUID actor,long version,int total,Instant created,Instant updated){}
    private Meta meta(OrganizationContacts.Access a,UUID id){var rows=jdbc.query("SELECT organization_id,facility_id,creator_account_id,version,total_rows,created_at,updated_at FROM merchant.organization_contact_import_job WHERE organization_id=? AND id=? AND creator_account_id=?",(r,n)->new Meta(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getLong(4),r.getInt(5),r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant()),contacts.org(a),id,a.actorAccountId());if(rows.size()!=1)throw fail("RESOURCE_NOT_FOUND");var m=rows.getFirst();permit(a,m.facility());return m;}
    @Override public Job preview(OrganizationContacts.Access a,String template,UUID facility,String csv,UUID key){permit(a,facility);a.scope().requireActiveFacility(facility);if(!"ORG_CONTACTS_CSV_1".equals(template))throw fail("VALIDATION_FAILED");String payload=JSON.writeValueAsString(Arrays.asList(template,facility,csv));var old=contacts.prior(a,"IMPORT_PREVIEW",key);if(old.isPresent()){var p=old.get();meta(a,p.target());contacts.verify(a,"IMPORT_PREVIEW",p.target(),0,payload,p);return at(a,p.target(),p.version(),0);}var rows=OrganizationContactCsv.parse(facility,csv);UUID id=UUID.randomUUID();Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);jdbc.update("INSERT INTO merchant.organization_contact_import_job VALUES(?,?,?,?,1,?,?,?)",id,contacts.org(a),facility,a.actorAccountId(),rows.size(),Timestamp.from(now),Timestamp.from(now));for(Row row:rows)jdbc.update("INSERT INTO merchant.organization_contact_import_row VALUES(?,?,?,?::jsonb,?::jsonb,NULL,NULL)",id,contacts.org(a),row.rowNumber(),row.input()==null?null:JSON.writeValueAsString(row.input()),JSON.writeValueAsString(row.errors()));contacts.evidence(a,"IMPORT_PREVIEW",key,id,facility,0,now,payload,null);return get(a,id,0);}
    private Job at(OrganizationContacts.Access a,UUID id,long version,int page){if(page<0)throw fail("VALIDATION_FAILED");var m=meta(a,id);var rows=jdbc.query("SELECT row_number,proposed_input::text,errors::text,contact_id,created_job_version FROM merchant.organization_contact_import_row WHERE job_id=? AND organization_id=? ORDER BY row_number",(r,n)->{var in=r.getString(2)==null?null:JSON.readValue(r.getString(2),OrganizationContacts.Input.class);boolean created=r.getObject(5)!=null&&r.getLong(5)<=version;return new Row(r.getInt(1),in==null?"INVALID":created?"CREATED":"VALID",in,Arrays.asList(JSON.readValue(r.getString(3),String[].class)),created?r.getObject(4,UUID.class):null);},id,contacts.org(a));int created=(int)rows.stream().filter(row->row.state().equals("CREATED")).count(),invalid=(int)rows.stream().filter(row->row.state().equals("INVALID")).count();Instant stamp=jdbc.queryForObject("SELECT occurred_at FROM merchant.organization_contact_command_receipt WHERE target_id=? AND result_version=?",Timestamp.class,id,version).toInstant();return new Job(id,m.org(),m.facility(),m.actor(),"ORG_CONTACTS_CSV_1",version,m.total(),m.total()-created-invalid,invalid,created,m.created(),stamp,rows.stream().skip(Math.multiplyExact((long)page,20)).limit(20).toList(),page,20,rows.size()>(page+1L)*20);}
    @Override public Job get(OrganizationContacts.Access a,UUID id,int page){return at(a,id,meta(a,id).version(),page);}
    @Override public Page list(OrganizationContacts.Access a,int page){if(page<0)throw fail("VALIDATION_FAILED");UUID org=contacts.org(a);boolean all=a.scope().permits("contacts.read",null)&&a.scope().permits("contacts.write",null)&&a.scope().permits("contacts.import",null);Set<UUID> sites=new HashSet<>(a.scope().facilities("contacts.import"));sites.removeIf(f->!a.scope().permits("contacts.write",f)||!a.scope().permits("contacts.read",f));if(!all&&sites.isEmpty())throw fail("RESOURCE_NOT_FOUND");List<Object> args=new ArrayList<>(List.of(org,a.actorAccountId()));String where="organization_id=? AND creator_account_id=?";if(!all){where+=" AND facility_id IN ("+String.join(",",Collections.nCopies(sites.size(),"?"))+")";args.addAll(sites);}args.add(Math.multiplyExact((long)page,20));var ids=jdbc.query("SELECT id FROM merchant.organization_contact_import_job WHERE "+where+" ORDER BY updated_at DESC,id ASC LIMIT 21 OFFSET ?",(r,n)->r.getObject(1,UUID.class),args.toArray());return new Page(ids.stream().limit(20).map(id->get(a,id,0)).toList(),page,20,ids.size()>20);}
    @Override public Job commit(OrganizationContacts.Access a,UUID id,List<Integer> selected,long version,UUID key){var m=meta(a,id);a.scope().requireActiveFacility(m.facility());if(selected==null||selected.isEmpty()||selected.size()>20||new HashSet<>(selected).size()!=selected.size()||selected.stream().anyMatch(n->n==null||n<1||n>m.total()))throw fail("VALIDATION_FAILED");var ordered=selected.stream().sorted().toList();String payload=JSON.writeValueAsString(ordered);var old=contacts.prior(a,"IMPORT_COMMIT",key);if(old.isPresent()){contacts.verify(a,"IMPORT_COMMIT",id,version,payload,old.get());return at(a,id,old.get().version(),0);}if(m.version()!=version)throw fail("PRECONDITION_STALE");
        List<OrganizationContacts.Input> inputs=new ArrayList<>();for(Integer row:ordered){var values=jdbc.query("SELECT proposed_input::text FROM merchant.organization_contact_import_row WHERE job_id=? AND row_number=? AND proposed_input IS NOT NULL AND contact_id IS NULL",(r,n)->JSON.readValue(r.getString(1),OrganizationContacts.Input.class),id,row);if(values.size()!=1)throw fail("IMPORT_ROW_NOT_VALID");inputs.add(values.getFirst());}
        Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);jdbc.update("UPDATE merchant.organization_contact_import_job SET version=version+1,updated_at=? WHERE id=? AND version=?",Timestamp.from(now),id,version);
        for(int i=0;i<ordered.size();i++){int row=ordered.get(i);UUID rowKey=UUID.nameUUIDFromBytes((id+":"+row).getBytes(StandardCharsets.UTF_8));var c=contacts.create(a,inputs.get(i),rowKey);jdbc.update("UPDATE merchant.organization_contact_import_row SET contact_id=?,created_job_version=? WHERE job_id=? AND row_number=?",c.id(),version+1,id,row);}
        contacts.evidence(a,"IMPORT_COMMIT",key,id,m.facility(),version,now,payload,null);return get(a,id,0);
    }
    @Override public Export export(OrganizationContacts.Access a,OrganizationContacts.Query q){UUID org=contacts.org(a);if(q.facilityId()!=null)contacts.permit(a,"contacts.export",q.facilityId());if(!a.scope().permits("contacts.export",null)&&a.scope().facilities("contacts.export").isEmpty())throw fail("RESOURCE_NOT_FOUND");List<OrganizationContacts.Contact> rows=new ArrayList<>();for(int p=0;p<=10;p++){var page=contacts.list(a,new OrganizationContacts.Query(p,20,q.search(),q.kind(),q.state(),q.facilityId(),q.group()));for(var row:page.items()){contacts.permit(a,"contacts.export",row.facilityId());rows.add(row);}if(rows.size()>200)throw fail("EXPORT_LIMIT_EXCEEDED");if(!page.hasNext())break;if(p==10)throw fail("EXPORT_LIMIT_EXCEEDED");}UUID id=UUID.randomUUID();Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);byte[] digest=hashes.hash(hashes.activeKey(),"organizationContactExport",id,1,org.toString(),a.actorAccountId().toString(),JSON.writeValueAsString(q));try{jdbc.update("INSERT INTO merchant.organization_contact_export_audit VALUES(?,?,?,?,?::uuid[],?,?,?,?)",id,org,a.actorAccountId(),a.requestId(),"{"+String.join(",",rows.stream().map(c->c.id().toString()).toList())+"}",rows.size(),hashes.activeKey(),digest,Timestamp.from(now));}finally{Arrays.fill(digest,(byte)0);}a.requireCurrent();return new Export(id,org,now,"LOCAL_TEST_SIMULATION",rows.size(),rows);}
}
